param([ValidateSet('locomotor-sets','dependency-metadata')][string]$Scope='locomotor-sets')
$ErrorActionPreference='Stop'
Set-Location (Resolve-Path "$PSScriptRoot/../..")
$out=Join-Path $env:RUNNER_TEMP 'upheaval-gameobject-sets'
$report="recovery/evidence/upheaval/$env:GITHUB_RUN_ID-$env:GITHUB_RUN_ATTEMPT/gameobject-sets"
New-Item -ItemType Directory -Force $out,$report|Out-Null
Copy-Item SDK/tools/*.dll $out
$csc="$env:WINDIR/Microsoft.NET/Framework/v4.0.30319/csc.exe"
$rows=@()
foreach($mode in @('Od','O2')){
    cl /nologo /clr /LD /MD /EHa /$mode /fp:precise /AI"$out" /Fo"$out/" /Fe"$out/Recovered.GameObject.dll" recovery/src/Native/Relocation.cpp recovery/src/Native/ScalarParsing.cpp recovery/src/Native/DataInitializers.cpp recovery/src/Native/ResourceMarshaling.cpp recovery/src/Native/EnumBitset.cpp recovery/src/Native/ObjectFilter.cpp recovery/src/Native/WeaponSlotOrder.cpp recovery/src/Native/GameObject.cpp recovery/src/Bridge/GameObjectCompiler.cpp *> "$report/build-$mode.txt"
 if($LASTEXITCODE -ne 0){Get-Content "$report/build-$mode.txt";throw 'GameObject build failed'}
    & $csc /nologo /platform:x86 /r:"$out/Recovered.GameObject.dll" /r:"$out/BinaryAssetBuilder.Core.dll" /out:"$out/GameObjectOracle.exe" (Resolve-Path 'recovery/tests/GameObjectOracle.cs') (Resolve-Path 'recovery/tests/GameObjectCases.cs') (Resolve-Path 'recovery/tests/GameObjectKindOf.cs') (Resolve-Path 'recovery/tests/GameObjectWeaponSetCases.cs') (Resolve-Path 'recovery/tests/GameObjectHealingCases.cs') (Resolve-Path 'recovery/tests/GameObjectCrateCases.cs') (Resolve-Path 'recovery/tests/GameObjectAIUpdateCases.cs') (Resolve-Path 'recovery/tests/GameObjectEconomyCases.cs') (Resolve-Path 'recovery/tests/GameObjectAssistCases.cs') (Resolve-Path 'recovery/tests/GameObjectSpawnUpdateCases.cs') (Resolve-Path 'recovery/tests/GameObjectSpawnCrateWatcherCases.cs') (Resolve-Path 'recovery/tests/GameObjectQueueParkingCases.cs') (Resolve-Path 'recovery/tests/GameObjectBuildingStructureCases.cs') (Resolve-Path 'recovery/tests/GameObjectEconomyPowerCases.cs') (Resolve-Path 'recovery/tests/GameObjectStructureWallCases.cs') (Resolve-Path 'recovery/tests/GameObjectCombatResponseCases.cs') (Resolve-Path 'recovery/tests/GameObjectStatusEffectsCases.cs') (Resolve-Path 'recovery/tests/GameObjectStealthVisionCases.cs') (Resolve-Path 'recovery/tests/GameObjectTiberiumCases.cs') (Resolve-Path 'recovery/tests/GameObjectWallEncloseCases.cs') (Resolve-Path 'recovery/tests/GameObjectResourceAlliesCases.cs') (Resolve-Path 'recovery/tests/GameObjectStateEventCases.cs') (Resolve-Path 'recovery/tests/GameObjectModelConditionCases.cs') (Resolve-Path 'recovery/tests/GameObjectMotionCleanupCases.cs') (Resolve-Path 'recovery/tests/GameObjectSpecialPowerBaseCases.cs') (Resolve-Path 'recovery/tests/GameObjectSpecialPowerDerivedCases.cs') (Resolve-Path 'recovery/tests/GameObjectPowerRoutingCases.cs') (Resolve-Path 'recovery/tests/GameObjectSpecialAbilityCases.cs') (Resolve-Path 'recovery/tests/GameObjectAbilityWeaponCases.cs') (Resolve-Path 'recovery/tests/GameObjectPowerCreationCases.cs') (Resolve-Path 'recovery/tests/GameObjectAbilityMovementCases.cs') (Resolve-Path 'recovery/tests/GameObjectAbilityStateCases.cs') (Resolve-Path 'recovery/tests/GameObjectAbilityRoutingCases.cs') (Resolve-Path 'recovery/tests/GameObjectAbilityResourceCases.cs') (Resolve-Path 'recovery/tests/GameObjectAbilityToggleCases.cs') (Resolve-Path 'recovery/tests/GameObjectAbilityFinishCases.cs') (Resolve-Path 'recovery/tests/GameObjectAttachCases.cs') (Resolve-Path 'recovery/tests/GameObjectUtilityCases.cs') (Resolve-Path 'recovery/tests/GameObjectAreaCases.cs') (Resolve-Path 'recovery/tests/GameObjectSupportCases.cs') (Resolve-Path 'recovery/tests/GameObjectObjectControlCases.cs') (Resolve-Path 'recovery/tests/GameObjectSlowDeathCases.cs') (Resolve-Path 'recovery/tests/GameObjectContainCoreCases.cs') (Resolve-Path 'recovery/tests/GameObjectContainRemainingCases.cs') (Resolve-Path 'recovery/tests/GameObjectDrawBeamCases.cs') (Resolve-Path 'recovery/tests/GameObjectDrawModelCases.cs') *> "$report/host-$mode.txt"
 if($LASTEXITCODE -ne 0){Get-Content "$report/host-$mode.txt";throw 'Sets oracle build failed'}
 '<configuration><startup useLegacyV2RuntimeActivationPolicy="true"><supportedRuntime version="v4.0" /></startup></configuration>'|Set-Content "$out/GameObjectOracle.exe.config"
 & "$out/GameObjectOracle.exe" "$out/BinaryAssetBuilder.Tokenizer.dll" $Scope *> "$report/oracle-$mode.txt"
 if($LASTEXITCODE -ne 0){Get-Content "$report/oracle-$mode.txt";throw 'Sets original DLL differential failed'}
 $summaries=@(Get-Content "$report/oracle-$mode.txt"|Where-Object{$_ -match ("^PASS "+[regex]::Escape($Scope)+" platform=")})
 if($summaries.Count -ne 4){throw 'Incomplete sets platform matrix'}
 $rows+=@{mode=$mode;platformSummaries=$summaries}
 Get-Content "$report/oracle-$mode.txt"|Where-Object{$_ -match ("^PASS "+[regex]::Escape($Scope)+" platform=")}
}
@{succeeded=$true;sourceCommit=$env:GITHUB_SHA;runId=$env:GITHUB_RUN_ID;scope=$Scope;modes=$rows}|ConvertTo-Json -Depth 8|Set-Content "$report/validation.json"
